9: /// <summary>
10: /// TEST-MCP-TRIAGE-003: Process spawning coverage for local triage agent execution. The class runs in
11: /// <see cref="ProcessEnvironmentCollection"/> because its case sets and restores GH_TOKEN in the process environment,
12: /// the baseline the production delta compares against (TR-MCP-USECASE-018 AC-006 and TR-MCP-USECASE-019 AC-008 as
13: /// appended on 2026-10-29; hostile validation round 8b finding R8B-F1). The rule itself is proved on explicit maps in
14: /// <see cref="EnvironmentDeltaContractTests"/>.
15: /// </summary>
16: [Trait("Category", "Integration")]
17: [Collection(ProcessEnvironmentCollection.Name)]
18: public sealed class DesktopProcessSpawnerTests
19: {
20:     /// <summary>
21:     /// TEST-MCP-TRIAGE-003: Desktop process launches pass only explicit
22:     /// environment deltas so the desktop user's profile environment remains
23:     /// authoritative for auth caches and temp folders. Native binding of the delta rule against the real process
24:     /// environment: the case owns its GH_TOKEN baseline (set to a value other than the child's, restored afterwards),
25:     /// so its outcome does not depend on the ambient token. TEMP is also set to a fixed baseline and restored;
26:     /// the unchanged-temp assertion always runs (TR-MCP-USECASE-018 AC-006, slice M SVC-2).
27:     /// </summary>
28:     [Fact]
29:     public void ExtractEnvironment_RemovesServiceDefaultsAndKeepsExplicitDeltas()
30:     {
31:         var previousToken = Environment.GetEnvironmentVariable("GH_TOKEN");
32:         var previousTemp = Environment.GetEnvironmentVariable("TEMP");
33:         Environment.SetEnvironmentVariable("GH_TOKEN", "baseline-token");
34:         Environment.SetEnvironmentVariable("TEMP", "/fixture-owned-temp-baseline");
35:         try
36:         {
37:             var startInfo = new ProcessStartInfo
38:             {
39:                 FileName = "codex",
40:                 UseShellExecute = false,
41:             };
42:             var path = startInfo.Environment.TryGetValue("PATH", out var existingPath)
43:                 ? existingPath
44:                 : Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
45:             startInfo.Environment["PATH"] = $"C:\\Users\\example\\AppData\\Roaming\\npm;{path}";
46:             startInfo.Environment["GH_TOKEN"] = "test-token";
47: 
48:             var deltas = DesktopProcessSpawner.ExtractEnvironment(startInfo);
49: 
50:             Assert.NotNull(deltas);
51:             Assert.Equal("test-token", deltas["GH_TOKEN"]);
52:             Assert.StartsWith("C:\\Users\\example\\AppData\\Roaming\\npm;", deltas["PATH"], StringComparison.OrdinalIgnoreCase);
53:             Assert.DoesNotContain("TEMP", deltas.Keys, StringComparer.OrdinalIgnoreCase);
54:         }
55:         finally
56:         {
57:             Environment.SetEnvironmentVariable("GH_TOKEN", previousToken);
58:             Environment.SetEnvironmentVariable("TEMP", previousTemp);
59:         }
60:     }
61: }
