52:     /// <summary>
53:     /// TEST-MCP-QBOLLAMA-001: Assigns the local Ollama default model to all four slots and verifies representative
54:     /// prompts trigger the normal Creativity, Logic, and Arbiter workflow with non-empty OpenAI-compatible responses.
55:     /// </summary>
56:     [Theory]
57:     [InlineData("Hello")]
58:     [InlineData("Create Hello World in C++")]
59:     public async Task ChatCompletions_LocalOllamaDefaultModel_TriggersNormalBrainSlots(string prompt)
60:     {
61:         var modelId = await ResolveDefaultOllamaModelAsync().ConfigureAwait(true);
62:         var chatClientFactory = new RecordingBrainSlotChatClientFactory();
63:         using var app = BuildFactory(chatClientFactory);
64:         using var seedClient = SeedClient(app);
65:         var promptSlug = NormalizeIdentifierSuffix(prompt);
66:         var sessionId = BuildSessionId("ollama-" + promptSlug);
67:         var turnId = NewRequestId("ollama-" + promptSlug);
68: 
69:         await SeedOllamaQuadAsync(seedClient, modelId).ConfigureAwait(true);
70:         await AssertQuadReadyAsync(seedClient).ConfigureAwait(true);
71:         await OpenSessionAsync(seedClient, sessionId).ConfigureAwait(true);
72:         await BeginTurnAsync(seedClient, sessionId, turnId, prompt).ConfigureAwait(true);
73: 
74:         using var client = Authorized(app, sessionId, turnId);
75:         var body = await PostAsync(client, RequestWithPrompt(prompt)).ConfigureAwait(true);
76: 
77:         var choice = Assert.Single(body.Choices);
78:         Assert.Equal("qbagent", body.Model);
79:         Assert.Equal("stop", choice.FinishReason);
80:         Assert.False(
81:             string.IsNullOrWhiteSpace(choice.Message.Content),
82:             "Expected non-empty assistant content. Per-role Ollama outputs: " + string.Join(" | ", chatClientFactory.InvokedOutputs));
83:         AssertQBAgentWorkflowRoles(chatClientFactory.InvokedRoles);
84:         Assert.All(chatClientFactory.InvokedModelIds, value => Assert.Equal(modelId, value));
85:         Assert.All(chatClientFactory.InvokedEndpoints, value => Assert.Equal(OllamaOpenAiEndpoint, value));
86:         await AssertSessionLogCapturedBrainOutputsAsync(
87:                 seedClient,
88:                 nameof(ChatCompletions_LocalOllamaDefaultModel_TriggersNormalBrainSlots),
89:                 prompt,
90:                 sessionId,
91:                 turnId,
92:                 modelId,
93:                 OllamaOpenAiEndpoint,
94:                 chatClientFactory.InvokedRoles,
95:                 chatClientFactory.InvokedOutputs,
96:                 choice.Message.Content)
97:             .ConfigureAwait(true);
98:     }
