6: $zone=[TimeZoneInfo]::FindSystemTimeZoneById('America/Chicago')
7: $asks=@{}
8: $events=[Collections.Generic.List[object]]::new()
9: $edits=[Collections.Generic.List[object]]::new()
10: $lineNumber=0
11: $parseFailures=[Collections.Generic.List[int]]::new()
12: foreach($line in [IO.File]::ReadLines($path)){
13:     $lineNumber++
14:     try{$item=$line|ConvertFrom-Json -Depth 100 -DateKind String}catch{$parseFailures.Add($lineNumber);continue}
15:     if(-not $item.timestamp){continue}
16:     $utc=[DateTimeOffset]::Parse($item.timestamp,[Globalization.CultureInfo]::InvariantCulture).ToUniversalTime()
17:     if($utc -lt [DateTimeOffset]'2026-10-19T00:00:00Z'){continue}
18:     $local=[TimeZoneInfo]::ConvertTime($utc,$zone).ToString('yyyy-MM-ddTHH:mm:sszzz')
19:     $content=$item.message.content
20:     if($item.type -eq 'user' -and $content -is [string] -and -not $item.isMeta){
21:         $events.Add([ordered]@{Line=$lineNumber;Utc=$utc.ToString('o');Local=$local;Kind='operator';Text=$content})
22:     }
23:     foreach($part in @($content)){
24:         if($part.type -eq 'tool_use'){
25:             if($part.name -match 'AskUserQuestion$'){
26:                 $asks[$part.id]=$part.input
27:                 $events.Add([ordered]@{Line=$lineNumber;Utc=$utc.ToString('o');Local=$local;Kind='question';Id=$part.id;Input=$part.input})
28:             }
29:             if($part.name -match '^(Write|Edit|MultiEdit)$' -and [string]$part.input.file_path -match '/(src|tests|build)/'){
30:                 $edits.Add([ordered]@{Line=$lineNumber;Utc=$utc.ToString('o');Local=$local;Tool=$part.name;Path=$part.input.file_path})
31:             }
32:         }
33:         if($item.type -eq 'user' -and $part.type -eq 'text' -and -not $item.isMeta){
34:             $events.Add([ordered]@{Line=$lineNumber;Utc=$utc.ToString('o');Local=$local;Kind='operator';Text=$part.text})
35:         }
36:         if($part.type -eq 'tool_result' -and $asks.ContainsKey([string]$part.tool_use_id)){
37:             $events.Add([ordered]@{Line=$lineNumber;Utc=$utc.ToString('o');Local=$local;Kind='answer';Id=$part.tool_use_id;Content=$part.content})
38:         }
39:     }
40: }
41: $marker=[IO.File]::ReadAllText('/home/sharpninja/github/McpServer/AGENTS-README-FIRST.yaml')
42: $output=[ordered]@{Source=$path;Lines=$lineNumber;ParseFailures=$parseFailures.ToArray();OperatorAndDecisionEvents=$events.ToArray();SourceEditChronology=$edits.ToArray()}
