380:     private static bool IsStrictlyInside(string path, string root)
381:     {
382:         if (!IsAbsolute(path) || !IsAbsolute(root)) return false;
383:         var pathSegments = Segments(path);
384:         if (pathSegments.Any(segment => segment is "." or ".."))
385:             return false;
386: 
387:         var rootSegments = Segments(root);
388:         if (pathSegments.Length <= rootSegments.Length)
389:             return false;
390: 
391:         var comparison = SegmentComparison(path, root);
392:         for (var index = 0; index < rootSegments.Length; index++)
393:         {
394:             if (!string.Equals(pathSegments[index], rootSegments[index], comparison))
395:                 return false;
396:         }
397: 
398:         return true;
399:     }
